<script setup lang="ts">import{onMounted,ref,computed}from'vue';import{wmApi}from'../api';import{statusLabel,type WmNews}from'@leadnews/shared';const rows=ref<WmNews[]>([]);onMounted(async()=>rows.value=(await wmApi.list()).records);const counts=computed(()=>Object.fromEntries(Object.keys({DRAFT:0,SUBMITTED:0,MANUAL_REVIEW:0,PUBLISHED:0,REJECTED:0}).map(k=>[k,rows.value.filter(x=>x.status===k).length])))</script><template><section class="hero"><h1>内容工作台</h1><p>从想法、审核到发布，状态清晰可追踪。</p></section><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px"><section v-for="(n,k) in counts" :key="k" class="panel"><p class="meta">{{statusLabel(String(k))}}</p><strong style="font-size:32px">{{n}}</strong></section></div></template>
